<script setup>
import { hrSiteName, hrUrl } from '@/utilities/hrUrl';import {Head,Link,usePage} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Button from '@/Components/Shadcn/Button.vue';import { ArrowLeft, Printer } from 'lucide-vue-next';defineOptions({layout:AppLayout});defineProps({records:[Array,Object],period:Object});const page=usePage();
const day=(v)=>v?new Intl.DateTimeFormat('fr-FR',{dateStyle:'short'}).format(new Date(`${String(v).slice(0,10)}T00:00:00`)):'—';
// Vue n'expose pas `window` au gabarit : l'impression passe par une fonction.
const printPage = () => window.print();
const dt=v=>v?new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';</script><template><Head title="Présences à imprimer"/><div class="mx-auto max-w-6xl space-y-3"><div class="print-actions flex justify-between"><Button :as="Link" :href="hrUrl('/administration/attendance')" size="rg" variant="white-outline"><ArrowLeft class="h-4 w-4 shrink-0" />Retour</Button><Button size="rg" @click="printPage"><Printer class="h-4 w-4 shrink-0" />Imprimer</Button></div><article class="print-doc bg-white p-8 text-slate-900"><header class="flex justify-between border-b-2 border-slate-900 pb-4"><div><strong class="uppercase">{{page.props.site?.brand||'Clinique Saint Georges'}}</strong><p class="text-xs">Site {{hrSiteName()}}</p></div><div class="text-end"><h1 class="text-xl font-black uppercase">Registre des présences</h1><p class="text-xs">Du {{day(period.from)}} au {{day(period.to)}}</p></div></header><table class="mt-8 w-full border-collapse text-xs"><thead><tr><th class="border border-slate-400 p-2 text-start">Employé</th><th class="border border-slate-400 p-2 text-start">Date</th><th class="border border-slate-400 p-2 text-start">Entrée</th><th class="border border-slate-400 p-2 text-start">Sortie</th><th class="border border-slate-400 p-2 text-start">Durée</th><th class="border border-slate-400 p-2 text-start">Observation</th></tr></thead><tbody><tr v-for="record in records" :key="record.uuid"><td class="border border-slate-300 p-2">{{record.employee.name}}<br>{{record.employee.employee_number}}</td><td class="border border-slate-300 p-2">{{day(record.work_date)}}</td><td class="border border-slate-300 p-2">{{dt(record.started_at)}}</td><td class="border border-slate-300 p-2">{{dt(record.ended_at)}}</td><td class="border border-slate-300 p-2">{{record.minutes===null?'Ouverte':`${Math.floor(record.minutes/60)} h ${record.minutes%60} min`}}</td><td class="border border-slate-300 p-2">{{record.observation||'—'}}</td></tr></tbody></table></article></div></template><style>@media print{.print-actions,aside,nav{display:none!important}.print-doc{padding:0!important}}</style>
